34	    pub fn path(&self) -> Option<&[OrderByHop]> {
35	        match self {
36	            OrderBy::Scalar(o) => Some(&o.path),
37	            OrderBy::ToManyAggregation(o) => Some(&o.path),
38	            OrderBy::ScalarAggregation(_) => None,
39	            OrderBy::Relevance(_) => None,
