45	            OrderBy::Scalar(o) => o.sort_order,
46	            OrderBy::ScalarAggregation(o) => o.sort_order,
47	            OrderBy::ToManyAggregation(o) => o.sort_order,
48	            OrderBy::Relevance(o) => o.sort_order,
49	        }
50	    }
