53	        match self {
54	            OrderBy::Scalar(o) => Some(o.field.clone()),
55	            OrderBy::ScalarAggregation(o) => Some(o.field.clone()),
56	            OrderBy::ToManyAggregation(_) => None,
57	            OrderBy::Relevance(_) => None,
58	        }
