33	impl OrderByBuilder {
34	    /// Builds all expressions for an `ORDER BY` clause based on the query arguments.
35	    pub(crate) fn build(&mut self, query_arguments: &QueryArguments, ctx: &Context<'_>) -> Vec<OrderByDefinition> {
36	        let needs_reversed_order = query_arguments.needs_reversed_order();
37	
38	        query_arguments
39	            .order_by
40	            .iter()
41	            .map(|order_by| match order_by {
42	                OrderBy::Scalar(order_by) => self.build_order_scalar(order_by, needs_reversed_order, ctx),
43	                OrderBy::ScalarAggregation(order_by) => {
44	                    self.build_order_aggr_scalar(order_by, needs_reversed_order, ctx)
45	                }
46	                OrderBy::ToManyAggregation(order_by) => self.build_order_aggr_rel(order_by, needs_reversed_order, ctx),
47	                OrderBy::Relevance(order_by) => self.build_order_relevance(order_by, needs_reversed_order, ctx),
48	            })
49	            .collect_vec()
50	    }
51	
52	    fn build_order_scalar(
53	        &mut self,
54	        order_by: &OrderByScalar,
55	        needs_reversed_order: bool,
56	        ctx: &Context<'_>,
57	    ) -> OrderByDefinition {
58	        let (joins, order_column) = self.compute_joins_scalar(order_by, ctx);
59	        let order: Option<Order> = Some(into_order(
60	            &order_by.sort_order,
61	            order_by.nulls_order.as_ref(),
62	            needs_reversed_order,
63	        ));
64	        let order_definition: OrderDefinition = (order_column.clone().into(), order);
65	
66	        OrderByDefinition {
67	            order_column: order_column.into(),
68	            order_definition,
69	            joins,
70	        }
71	    }
72	
73	    fn build_order_relevance(
74	        &mut self,
75	        order_by: &OrderByRelevance,
76	        needs_reversed_order: bool,
77	        ctx: &Context<'_>,
78	    ) -> OrderByDefinition {
79	        let columns: Vec<Expression> = order_by
80	            .fields
81	            .iter()
82	            .map(|sf| sf.as_column(ctx).opt_table(self.parent_alias.clone()).into())
83	            .collect();
84	        let order_column: Expression = text_search_relevance(&columns, order_by.search.clone()).into();
85	        let order: Option<Order> = Some(into_order(&order_by.sort_order, None, needs_reversed_order));
86	        let order_definition: OrderDefinition = (order_column.clone(), order);
87	
88	        OrderByDefinition {
89	            order_column,
90	            order_definition,
91	            joins: vec![],
92	        }
93	    }
94	
95	    fn build_order_aggr_scalar(
96	        &mut self,
97	        order_by: &OrderByScalarAggregation,
98	        needs_reversed_order: bool,
99	        ctx: &Context<'_>,
100	    ) -> OrderByDefinition {
101	        let order: Option<Order> = Some(into_order(&order_by.sort_order, None, needs_reversed_order));
102	        let order_column = order_by.field.as_column(ctx);
103	        let order_definition: OrderDefinition = match order_by.sort_aggregation {
104	            SortAggregation::Count => (count(order_column.clone()).into(), order),
105	            SortAggregation::Avg => (avg(order_column.clone()).into(), order),
106	            SortAggregation::Sum => (sum(order_column.clone()).into(), order),
107	            SortAggregation::Min => (min(order_column.clone()).into(), order),
108	            SortAggregation::Max => (max(order_column.clone()).into(), order),
109	        };
110	
111	        OrderByDefinition {
112	            order_column: order_column.into(),
113	            order_definition,
114	            joins: vec![],
115	        }
116	    }
117	
118	    fn build_order_aggr_rel(
119	        &mut self,
120	        order_by: &OrderByToManyAggregation,
121	        needs_reversed_order: bool,
122	        ctx: &Context<'_>,
