124	        let order: Option<Order> = Some(into_order(&order_by.sort_order, None, needs_reversed_order));
125	        let (joins, order_column) = self.compute_joins_aggregation(order_by, ctx);
126	        let order_definition: OrderDefinition = match order_by.sort_aggregation {
127	            SortAggregation::Count => {
