9	    fn m2m_columns(&self, ctx: &Context<'_>) -> Vec<Column<'static>>;
10	    fn join_columns(&self, ctx: &Context<'_>) -> ColumnIterator;
11	    fn identifier_columns(&self, ctx: &Context<'_>) -> ColumnIterator;
