15	impl RelationFieldExt for RelationField {
16	    fn m2m_columns(&self, ctx: &Context<'_>) -> Vec<Column<'static>> {
17	        let is_side_a = self.walker().relation().relation_fields().next().map(|rf| rf.id) == Some(self.id);
18	        let prefix = if is_side_a { "B" } else { "A" };
19	        vec![Column::from(prefix).table(self.as_table(ctx))]
20	    }
21	
22	    fn join_columns(&self, ctx: &Context<'_>) -> ColumnIterator {
23	        let relation = self.walker().relation();
24	        match relation.refine() {
25	            walkers::RefinedRelationWalker::ImplicitManyToMany(m) => {
26	                let is_side_a = relation.relation_fields().next().map(|rf| rf.id) == Some(self.id);
27	                let column_name = if is_side_a {
28	                    m.column_b_name()
29	                } else {
30	                    m.column_a_name()
31	                };
32	                ColumnIterator::from(vec![column_name.into()])
33	            }
34	            _ => ModelProjection::from(self.linking_fields()).as_columns(ctx),
35	        }
36	    }
37	
38	    fn identifier_columns(&self, ctx: &Context<'_>) -> ColumnIterator {
39	        let relation = self.walker().relation();
40	        match relation.refine() {
41	            walkers::RefinedRelationWalker::ImplicitManyToMany(m) => {
42	                let is_side_a = relation.relation_fields().next().map(|rf| rf.id) == Some(self.id);
43	                let column_name = if is_side_a {
44	                    m.column_a_name()
45	                } else {
46	                    m.column_b_name()
47	                };
48	                ColumnIterator::from(vec![column_name.into()])
49	            }
50	            _ => ModelProjection::from(self.model().primary_identifier()).as_columns(ctx),
51	        }
52	    }
53	
54	    fn as_table(&self, ctx: &Context<'_>) -> Table<'static> {
55	        if self.relation().is_many_to_many() {
56	            self.related_field().relation().as_table(ctx)
57	        } else {
58	            self.model().as_table(ctx)
59	        }
60	    }
61	}
