452	fn cursor_order_def_scalar(order_by: &OrderByScalar, order_by_def: &OrderByDefinition) -> CursorOrderDefinition {
453	    // If there are any ordering hops, this finds the foreign key fields for the _last_ hop (we look for the last one because the ordering is done the last one).
454	    // These fk fields are needed to check whether they are nullable
455	    // cf: part #2 of the SQL query above, when a field is nullable.
456	    let fks = foreign_keys_from_order_path(&order_by.path, &order_by_def.joins);
457	
458	    CursorOrderDefinition {
459	        sort_order: order_by.sort_order,
460	        order_column: order_by_def.order_column.clone(),
461	        order_fks: fks,
462	        on_nullable_fields: !order_by.field.is_required(),
463	    }
464	}
