470	) -> CursorOrderDefinition {
471	    let coalesce_exprs: Vec<Expression> = vec![order_by_def.order_column.clone(), Value::int32(0).into()];
472	
473	    // We coalesce the order column to 0 when it's compared to the cmp table since the aggregations joins
474	    // might return NULL on relations that have no connected records
475	    let order_column: Expression = coalesce(coalesce_exprs).into();
476	
