520	fn foreign_keys_from_order_path(path: &[OrderByHop], joins: &[AliasedJoin]) -> Option<Vec<CursorOrderForeignKey>> {
521	    let (before_last_hop, last_hop) = take_last_two_elem(path);
522	
523	    last_hop.map(|hop| {
524	        match hop {
525	            OrderByHop::Relation(rf) => {
526	                rf.scalar_fields()
527	                    .into_iter()
528	                    .map(|fk_field| {
529	                        // If there are _more than one_ hop, we need to refer to the fk fields using the
530	                        // join alias of the hop _before_ the last hop. eg:
531	                        //
532	                        // ```sql
533	                        // SELECT ...
534	                        // FROM
535	                        //  "public"."ModelA"
536	                        //   LEFT JOIN "public"."ModelB" AS "orderby_0_ModelB" ON (
537	                        //     "public"."ModelA"."b_id" = "orderby_0_ModelB"."id"
538	                        //   )
539	                        //   LEFT JOIN "public"."ModelC" AS "orderby_0_ModelC" ON (
540	                        //     "orderby_0_ModelB"."c_id" = "orderby_0_ModelC"."id"
541	                        //   )
542	                        // WHERE
543	                        // ( ... OR <before_last_join_alias>.<foreign_key_db_name> IS NULL )
544	                        // ```
545	                        // In the example above, <before_last_join_alias> == "orderby_0_ModelB"
546	                        //                          <foreign_key_db_name> == "c_id"
547	                        match before_last_hop {
548	                            Some(_) => {
549	                                let (before_last_join, _) = take_last_two_elem(joins);
550	                                let before_last_join = before_last_join
551	                                    .expect("There should be an equal amount of order by hops and joins");
552	
553	                                CursorOrderForeignKey {
554	                                    field: fk_field,
555	                                    alias: Some(before_last_join.alias.to_owned()),
556	                                }
557	                            }
558	                            None => {
559	                                // If there is not more than one hop, then there's no need to alias the fk field
560	                                CursorOrderForeignKey {
561	                                    field: fk_field,
562	                                    alias: None,
563	                                }
564	                            }
565	                        }
566	                    })
567	                    .collect_vec()
568	            }
569	            OrderByHop::Composite(_) => unreachable!("SQL connectors don't have composite support."),
570	        }
571	    })
572	}
