575	fn take_last_two_elem<T>(slice: &[T]) -> (Option<&T>, Option<&T>) {
576	    let len = slice.len();
577	
578	    match len {
579	        0 => (None, None),
580	        1 => (None, slice.first()),
581	        _ => (slice.get(len - 2), slice.get(len - 1)),
582	    }
583	}
