pub struct OrderByToManyAggregation {
    pub path: Vec<OrderByHop>,
    pub sort_order: SortOrder,
    pub sort_aggregation: SortAggregation,
}

impl OrderByToManyAggregation {
    /// Returns all the hops of the path except the final aggregation hop.
    /// These are the relations that need to be traversed (joined) before reaching
    /// the relation on which the aggregation is performed.
    pub fn intermediary_hops(&self) -> &[OrderByHop] {
        let len = self.path.len();

        debug_assert!(len > 0, "An order by relation aggregation has to have at least one hop");

        &self.path[..len - 1]
    }

    /// Returns the last hop in the order-by path, i.e. the relation on which the
    /// aggregation is performed.
    pub fn aggregation_hop(&self) -> &OrderByHop {
        self.path
            .last()
            .expect("An order by relation aggregation has to have at least one hop")
    }
