    let selection: Vec<_> = rs
        .args
        .order_by
        .iter()
        .flat_map(|order_by| match order_by {
            // Order by a scalar field on the related model itself: select the field so we can
            // order on it in the outer query.
            OrderBy::Scalar(x) if x.path.is_empty() => vec![x.field.clone()],
