            // are performed on the outer query, so we need to expose the linking fields of the
            // first hop so the outer query can join onto them.
            OrderBy::Scalar(x) => first_hop_linking_fields(&x.path),
            // Order by an aggregation reached through a (possibly nested) relation path: same as
            // above, we need the first hop's linking fields to be able to join in the outer query.
            OrderBy::ToManyAggregation(x) => first_hop_linking_fields(&x.path),
            OrderBy::Relevance(x) => x.fields.clone(),
            _ => Vec::new(),
        })
        .collect();

