///
/// When ordering by something reached through a relation path, the ordering joins are computed on
/// the outer query. To be able to join onto the first relation of the path, the inner (relation)
/// query must expose the linking fields of that first hop. These are the fields on the model
/// enclosing the first relation that link to the related records (a foreign key for one-to-many,
/// the primary identifier for many-to-many).
fn first_hop_linking_fields(hops: &[OrderByHop]) -> Vec<ScalarFieldRef> {
